// @ts-nocheck
/* eslint-disable */
/**
 * Sales-document form engine — qt. GENERATED by tools/sync-sales-doc-form.mjs from web/pages/sales_doc_qt_form.xhtml + its components — do not edit; change the script and run `npm run sales-doc-form:sync`.
 *
 * The page script(s) of the Java form, same behaviour line by line, on top of the engine scripts of sales-doc-libs.engine.ts (the scripts
 * its head loads: sales_doc_customer.js · sales_doc_pager.js · sales_doc_preview.js · sales_doc_print.js · sales_doc_print_quote.js · sales_doc_saved.js · sales_doc_search.js · sales_doc_items.js · sales_doc_attach.js · sales_doc_payment.js · sales_doc_validate.js · sales_doc_payload.js).
 *
 * WHY it is imperative DOM code and not Angular components: the Java page draws its HTML from data as strings. Porting it 1:1 is what
 * guarantees the screen, texts and states are identical to the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-sales-doc-form.mjs):
 *   - the environment is injected (SalesDocFormEnv): messages, fetch (the BFF contract of sales-doc-backend.ts), SweetAlert, navigation, the
 *     context path — in Java these were EL, the URL and globals;
 *   - the strip of tabs that sales_doc_tabs.xhtml injects into the Java top bar is drawn by the Angular shell (nav.config.ts);
 *   - global listeners and timers added through listen() / tmo(), the animation frames, the boxes the scripts move to <body> and the response
 *     guard are removed by the function returned from startSalesDocQt().
 */

import { createSalesDocLibs, createSalesDocRuntime } from './sales-doc-libs.engine';

export interface SalesDocFormEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** the BFF contract of the page: /board/prospect-list, /rvapi?action=materials, /board/prospect/attachments, /board/chat-master-data (see sales-doc-backend.ts) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<any>;
  /** window.location.href = … : a route of this app, or an absolute address of this origin (the link back to the list) */
  navigate: (address: string) => void;
  /** #{request.contextPath}: where the BFF is ("" here) */
  ctx: string;
}

export function startSalesDocQt(env: SalesDocFormEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });
  var rt = createSalesDocRuntime({ listen: listen, tmo: tmo, track: track });
  /* the engine scripts the head of the Java page loads, in its order */
  createSalesDocLibs(env, rt, ["customer","pager","preview","print","print_quote","saved","search","items","attach","payment","validate","payload"]);


  /* ---- inline script 1 of 2 of the page ---- */
  window.SalesDocPaymentMsg = {
              none_pick: env.t("label.pm.box_pick"),
              none_fill: env.t("label.pm.box_fill"),
              cash_none: env.t("label.pm.cash_none"),
              credit_term: env.t("label.pm.credit_term"),
              days: env.t("label.pm.days"),
              due_date: env.t("label.pm.due_date"),
              credit_hint: env.t("label.pm.credit_hint"),
              credit_need: env.t("label.pm.credit_need"),
              sub_schedule: env.t("label.pm.sub_schedule"),
              sub_deposit: env.t("label.pm.sub_deposit"),
              sub_prepaid: env.t("label.pm.sub_prepaid"),
              unit: env.t("label.pm.unit"),
              col_no: env.t("label.pm.col_no"),
              col_net: env.t("label.pm.col_net"),
              col_rate: env.t("label.pm.col_rate"),
              col_vat: env.t("label.pm.col_vat"),
              col_gross: env.t("label.pm.col_gross"),
              total: env.t("label.pm.total"),
              diff: env.t("label.pm.diff"),
              remain: env.t("label.pm.remain"),
              msg_nodoc: env.t("label.pm.msg_nodoc"),
              msg_equal_ok: env.t("label.pm.msg_equal_ok"),
              msg_equal_bad: env.t("label.pm.msg_equal_bad"),
              msg_need_one: env.t("label.pm.msg_need_one"),
              msg_le_ok: env.t("label.pm.msg_le_ok"),
              msg_le_bad: env.t("label.pm.msg_le_bad"),
              err_due: env.t("label.pm.err_due"),
              err_value: env.t("label.pm.err_value"),
              err_equal: env.t("label.pm.err_equal"),
              err_over: env.t("label.pm.err_over"),
              v_credit: env.t("label.pm.v_credit"),
              v_fill: env.t("label.pm.v_fill"),
              v_not_equal: env.t("label.pm.v_not_equal"),
              v_over: env.t("label.pm.v_over"),
              row_del: env.t("label.pm.row_del")
          };
  /* ---- inline script 2 of 2 of the page ---- */
  (function () {
                  var CTX = env.ctx;
                  var MSG = {
                      removeItem: env.t("label.qt.remove_item"),
                      pickProduct: env.t("label.qt.pick_product"),
                      alertTitle: env.t("label.ld2.alert_title"),
                      needCustomer: env.t("label.qt.validate_customer"),
                      needItems: env.t("label.qt.validate_items"),
                      colQty: env.t("label.qt.col_qty"),
                      colPrice: env.t("label.qt.col_price"),
                      colDisc: env.t("label.qt.discount"),
                      vatChanged: env.t("label.pd.vat_changed")
                  };
                  var CUST_MSG = {
                      changeCustomer: env.t("label.qt.change_customer"),
                      searchCustomer: env.t("label.ld2.search_customer"),
                      editCustomer: env.t("label.qt.edit_customer"),
                      createCustomer: env.t("label.qt.create_customer"),
                      createAndPick: env.t("label.qt.create_and_pick"),
                      saveEdit: env.t("label.qt.save_edit"),
                      countryTh: env.t("label.qt.country_th"),
                      pick: env.t("label.qt.pick"),
                      noResult: env.t("label.qt.no_result"),
                      searchFailed: env.t("label.qt.search_failed"),
                      loading: env.t("label.qt.loading_search"),
                      fillRequired: env.t("label.qt.fill_required"),
                      taxId13: env.t("label.qt.taxid_13"),
                      lblName: env.t("label.qt.cust_name"),
                      lblTaxId: env.t("label.qt.tax_id_ph"),
                      lblAddr: env.t("label.sd.address"),
                      needCustomer: env.t("label.qt.validate_customer"),
                      vbTitle: env.t("label.cv.vb_title"),
                      branch5: env.t("label.cv.branch5")
                  };
                  function g(id) { return document.getElementById(id); }
                  function warn(text) { env.swal({ title: MSG.alertTitle, text: text, icon: 'warning', timer: 3000, buttons: false }); }
                  /* ★ 19/10 (Spec ฟิลด์ใบเสนอราคา): ตรวจรูปแบบ/ข้อความแจ้งเตือนทุกช่อง — ต้องผูกก่อนสร้างส่วนต่างๆ (ตารางรายการลงทะเบียนรูปแบบ QTY/PRICE/DISC ตอน init) */
                  var VAL = window.SalesDocValidate;
                  VAL.bind();

                  /* ยอดรวมล่าสุดจากตารางรายการ : "รวมทั้งสิ้น" ใช้เป็นยอดเอกสารของ pop-up รายละเอียดการชำระเงิน (★ 14/10) */
                  var totals = { grand: 0 };

                  /* ---------- ตารางรายการสินค้า + สรุปยอดรวม : resources/support/sales_doc_items.js ---------- */
                  var items = SalesDocItems.init({
                      prefix: 'qt',
                      ctx: CTX,
                      strict: true,
                      cellLabels: true,
                      msg: { removeItem: MSG.removeItem, pickProduct: MSG.pickProduct, colQty: MSG.colQty, colPrice: MSG.colPrice, colDisc: MSG.colDisc },
                      onChange: function (t) { totals = t; }
                  });

                  /* ---------- ลูกค้า (ส่วน B) + pop-up ค้นหา/แก้ไข : resources/support/sales_doc_customer.js ---------- */
                  var cust = SalesDocCustomer.init({
                      prefix: 'qt',
                      ctx: CTX,
                      msg: CUST_MSG,
                      onChange: function (c) {
                          if (c && c.code != null && custHost()) { VAL.clear(custHost()); }   /* เลือกลูกค้าแล้ว — ล้างข้อความ "กรุณาเลือกลูกค้า" */
                      }
                  });

                  /* ---------- เอกสารแนบ : resources/support/sales_doc_attach.js (ไฟล์แนบกับทะเบียนลูกค้าที่เลือกในเอกสาร) ---------- */
                  SalesDocAttach.init({
                      prefix: 'qt',
                      ctx: CTX,
                      strict: true,
                      getProspectId: function () { var c = cust.get(); return c && c.id ? c.id : null; }
                  });

                  /* ★ 16/10 (Mockup QT v25 / SO v2): ถอดปุ่ม/pop-up "ค้นหาเอกสาร" ของเอกสารตัวเองออก (ไม่มีใน Spec) — ใบจองค้นใบเสนอราคาเพื่ออ้างอิงผ่านปุ่มที่หัวส่วนข้อมูลเอกสาร (SalesDocRef) */

                  /* ---------- ★ 16/10 (Mockup QT v25): วิธีการชำระเงิน (เงินสด / เครดิตเทอม / งวดสัญญา / มัดจำ / ล่วงหน้า) : resources/support/sales_doc_payment.js ----------
                     ไม่บังคับกรอกก่อนบันทึก แต่ถ้าเลือกแล้วต้องกรอกรายละเอียดให้ครบและผลรวมถูกต้อง (pay.validate) */
                  var pay = SalesDocPayment.init({
                      prefix: 'qt',
                      strict: true,
                      getGrand: function () { return totals.grand; },
                      getDocDate: function () { return g('qtDocDate').value; },
                      getVatRate: function () { return g('qtVatMode').value === 'exempt' ? 0 : 7; },
                      msg: { payDue: env.t("label.pm.due_date"), payNote: env.t("label.qt.remarks"), dateLabel: env.t("label.qt.quote_date") }
                  });
                  /* เปลี่ยนรูปแบบการคิด VAT (ทั้งเอกสาร หรือรายแถว) → ยอดรวมเอกสารเปลี่ยน ; ถ้าวิธีการชำระเงินเป็นตาราง (งวดสัญญา/มัดจำ/ล่วงหน้า) แล้วผลรวมไม่ตรง-เกินยอดใหม่ ให้เตือนไปแก้รายละเอียดการชำระเงิน
                     (change ที่โค้ดตั้งเอง = vmSync ไม่ใช่ผู้ใช้เปลี่ยน → ข้าม) */
                  function warnPaymentMismatch(e) {
                      if (e && e.vmSync) { return; }
                      if (pay.validate().length) { warn(MSG.vatChanged); }
                  }
                  g('qtVatMode').addEventListener('change', warnPaymentMismatch);
                  g('qtVatMode').addEventListener('vatrowchange', warnPaymentMismatch);

                  /* ---------- ปุ่มบันทึก : ตรวจ → บันทึก → pop-up "บันทึกเรียบร้อย" → (กดพิมพ์) หน้าตัวอย่างก่อนพิมพ์ — ★ 19/10 (Mockup QT v25) : resources/support/sales_doc_saved.js ---------- */
                  var saved = SalesDocSaved.init({
                      prefix: 'qt',
                      paper: g('qtPaper'),
                      docPrefix: 'QT',
                      listUrl: document.querySelector('.qt-back').href,
                      docNoField: 'qtDocNo'
                  });
                  function saveAndPreview() {
                      /* ★ 19/10 (Spec ส่วนที่ 2): ประกอบข้อมูลเอกสารครบทุกฟิลด์ (รวมที่ระบบเติม/คำนวณ) — ตรวจสูตรได้ที่ console ; มี API แล้วส่ง payload นี้ (pending = ฟิลด์ที่ยังหาค่าจาก master data ไม่ได้) */
                      var payload = SalesDocPayload.build({ prefix: 'qt', items: items, cust: cust, pay: pay });
                      console.debug('[qt] document payload', payload);
                      if (!payload.checks.ok) { console.warn('[qt] ยอดรวมของบรรทัดไม่ตรงหน้าจอ', payload.checks.errors); }
                      /* ★ ยังไม่มี API บันทึกใบเสนอราคา → เปิด pop-up ด้วยเลขที่ชั่วคราว + แถบแจ้งว่ายังไม่ได้บันทึกเข้าระบบ (persisted: false)
                         (มี API แล้ว: ยิงบันทึกตรงนี้ → เติมเลขที่ที่ได้ลง qtDocNo → saved.open({ docNo: เลขที่ที่ได้, persisted: true })) */
                      saved.open({ persisted: false });
                  }
                  /* ---------- ★ 19/10 (มาตรฐานการกรอกข้อมูลและการแจ้งเตือน G3/G4/A3): ตรวจทุกช่องตอนกดบันทึก ----------
                     ช่องที่มี data-vf/data-req ใน qtPaper + ตัวตรวจเพิ่ม (ลูกค้า / รายการสินค้า / วิธีการชำระเงิน) ; ไม่ผ่าน = แถบแดง "ยังบันทึกไม่ได้: ..." ครบทุกข้อ + เลื่อนไปช่องแรก (เปิดแท็บที่ซ่อนอยู่ให้) */
                  function custHost() { return g('qtCName') ? g('qtCName').closest('.qm-cus-nameline') : null; }
                  function checkCustomer() { return cust.get() ? VAL.flag(custHost(), '') : VAL.flag(custHost(), VAL.msg('pick_cust')); }
                  function checkItems() { return items.hasItem() ? VAL.flag(g('qtAddRow'), '') : VAL.flag(g('qtAddRow'), VAL.msg('no_items')); }
                  function checkPayment() { var errs = pay.validate(); return VAL.flag(g('qtPayBox'), errs.length ? errs[0] : ''); }
                  var saveBtn = g('qtSaveBtn');
                  if (saveBtn) {
                      saveBtn.addEventListener('click', function () {
                          if (VAL.validateDocument(g('qtPaper'), [checkCustomer, checkItems, checkPayment])) { saveAndPreview(); }
                      });
                  }

                  /* ---------- ค่าเริ่มต้น : วันที่เสนอราคา = วันนี้ (input type=date ใช้รูปแบบ yyyy-MM-dd) ---------- */
                  var dateEl = g('qtDocDate');
                  if (dateEl && !dateEl.value) {
                      var todayD = new Date();
                      var pad2 = function (n) { return String(n).padStart(2, '0'); };
                      dateEl.value = todayD.getFullYear() + '-' + pad2(todayD.getMonth() + 1) + '-' + pad2(todayD.getDate());
                  }
                  items.addRow();
              })();
  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = ["SalesDocCustomer","SalesDocPager","SalesDocPreview","SalesDocPrint","SalesDocPrintQuote","SalesDocSaved","SalesDocSearch","SalesDocItems","SalesDocAttach","SalesDocPayment","SalesDocValidate","SalesDocPayload","SalesDocPaymentMsg"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    rt.destroy();
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}

/** what the host has to load / start for this form (the Java head: attach_file_types.js, drag_scroll.js) */
export const SALES_DOC_QT_NEEDS = { attachFileTypes: true, dragScroll: ".qm-tbox" };
